            $totalSupplierRefund = bcadd($totalSupplierRefund, $supplierRefundAmount, 2);
            Log::info("订单 {$orderId} 添加供应商{$supplierId}退款分账: 金额={$supplierRefundAmount}元, 子订单号={$supplierSubOrderId}");
        }

        // 9. 添加平台子订单（如果有剩余金额）
        $platformRefundAmount = bcsub((string)$refundAmount, $totalSupplierRefund, 2);

        if (bccomp($platformRefundAmount, '0', 2) > 0) {
            // 读取平台分账配置
            $configFile = config_path() . 'UmsPayConfig.json';
            if (file_exists($configFile)) {
