        // 10. 构造分账退款参数
        $divisionData = [
            'platformAmount' => 0,
            'subOrders' => $subOrders
        ];

        Log::info("订单 {$orderId} 多供应商退款分账数据构建成功: 子订单数=" . count($subOrders));

