/**
 * 构建多供应商订单的退款分账数据
 * 当主订单 supplier_id=0 时，需要按供应商维度分别构建退款分账子订单
 * 
 * @param array $order 订单信息
 * @param float $refundAmount 退款金额
 * @return array 分账退款数据
 */
private function buildMultiSupplierRefundDivisionData(array $order, float $refundAmount): array
{
    try {
        $orderId = $order['order_id'] ?? '';
        Log::info("订单 {$orderId} 开始构建多供应商退款分账数据");

        // 1. 查询订单商品信息，获取每个商品的供应商ID和结算价
        /** @var \app\services\order\StoreOrderCartInfoServices $cartInfoServices */
        $cartInfoServices = app()->make(\app\services\order\StoreOrderCartInfoServices::class);
        $cartInfos = $cartInfoServices->getOrderCartInfoSettlePrice((int)$order['id']);

        if (empty($cartInfos['info'])) {
            Log::warning("订单 {$orderId} 没有找到商品信息，无法构建多供应商退款分账数据");
            return [];
        }

        // 2. 按供应商汇总结算金额
        $supplierSettleTotals = [];
        foreach ($cartInfos['info'] as $cart) {
            $cartInfo = $cart['cart_info'] ?? [];
            $productInfo = $cartInfo['productInfo'] ?? [];
            $supplierId = $productInfo['supplier_id'] ?? 0;

            if ($supplierId > 0) {
                $itemSettlePrice = $productInfo['attrInfo']['settle_price'] ?? 0;
                $itemTotalSettle = bcmul((string)$itemSettlePrice, (string)$cart['cart_num'], 2);

                if (!isset($supplierSettleTotals[$supplierId])) {
                    $supplierSettleTotals[$supplierId] = '0.00';
                }
                $supplierSettleTotals[$supplierId] = bcadd($supplierSettleTotals[$supplierId], $itemTotalSettle, 2);
            }
        }

        if (empty($supplierSettleTotals)) {
            Log::info("订单 {$orderId} 没有供应商商品，按平台订单处理退款");
            return [];
        }

        Log::info("订单 {$orderId} 多供应商结算汇总: " . json_encode($supplierSettleTotals));

        // 3. 获取供应商信息（银联商户号）
        $supplierIds = array_keys($supplierSettleTotals);
        /** @var \app\services\supplier\SystemSupplierServices $supplierServices */
        $supplierServices = app()->make(\app\services\supplier\SystemSupplierServices::class);
        $suppliers = $supplierServices->getColumn([['id', 'in', $supplierIds]], 'id,supplier_name,unionpay_mid', 'id');

        // 4. 计算总结算金额
        $totalSettleAmount = array_sum(array_map('floatval', $supplierSettleTotals));

        if ($totalSettleAmount <= 0) {
            Log::warning("订单 {$orderId} 总结算金额为0，无法构建退款分账数据");
            return [];
        }

        // 5. 查询该订单的所有退款记录（已退金额）
        /** @var \app\dao\order\StoreOrderRefundDao $refundDao */
        $refundDao = app()->make(\app\dao\order\StoreOrderRefundDao::class);
        $refundRecords = $refundDao->search(['store_order_id' => $order['id'], 'is_del' => 0])
            ->where('refunded_price', '>', 0)
            ->column('refunded_price', 'id');
        $totalRefundedAmount = array_sum($refundRecords);
        Log::info("订单 {$orderId} 已退款总金额: {$totalRefundedAmount} 元");

        // 6. 查询分账记录，获取各供应商已收金额
        // 对于多供应商订单，分账记录可能使用主订单ID或子订单ID
        /** @var \app\services\supplier\SupplierShareRecordServices $shareRecordServices */
        $shareRecordServices = app()->make(\app\services\supplier\SupplierShareRecordServices::class);

        // 6.1 查询主订单的分账记录
        $onlineShareRecords = $shareRecordServices->getShareRecords([
            'order_id' => $order['id'],
            'division_type' => 'online'
        ]);

        // 6.2 查询子订单的分账记录（多供应商订单的分账记录通常在子订单上）
        /** @var \app\services\order\StoreOrderServices $storeOrderServices */
        $storeOrderServices = app()->make(\app\services\order\StoreOrderServices::class);
        $subOrdersList = $storeOrderServices->getColumn(['pid' => $order['id'], 'is_system_del' => 0], 'id,order_id,supplier_id', 'id');

        $subOrderShareRecords = [];
        if ($subOrdersList) {
            foreach ($subOrdersList as $subOrderItem) {
                $subOrderRecords = $shareRecordServices->getShareRecords([
                    'order_id' => $subOrderItem['id'],
                    'division_type' => 'online'
                ]);
                if ($subOrderRecords) {
                    $subOrderShareRecords = array_merge($subOrderShareRecords, $subOrderRecords);
                }
            }
        }

        // 合并主订单和子订单的分账记录
        $allShareRecords = array_merge($onlineShareRecords, $subOrderShareRecords);
        Log::info("订单 {$orderId} 分账记录: 主订单=" . count($onlineShareRecords) . "条, 子订单=" . count($subOrderShareRecords) . "条");

        // 按供应商汇总已收金额
        $supplierReceivedMap = [];
        if ($allShareRecords) {
            foreach ($allShareRecords as $record) {
                $supplierId = $record['supplier_id'] ?? 0;
                if ($supplierId > 0) {
                    if (!isset($supplierReceivedMap[$supplierId])) {
                        $supplierReceivedMap[$supplierId] = '0.00';
                    }
                    $supplierReceivedMap[$supplierId] = bcadd($supplierReceivedMap[$supplierId], (string)$record['share_amount'], 2);
                }
            }
        }

        // 7. 构建子订单基础
        $subOrderBase = $order['order_id'];

        // 8. 遍历每个供应商，计算退款金额并构建子订单
        $subOrders = [];
        $totalSupplierRefund = '0.00';

        // 计算总分账金额（用于退款比例计算）
        $totalShareAmount = array_sum(array_map('floatval', $supplierReceivedMap));
        if ($totalShareAmount <= 0) {
            Log::warning("订单 {$orderId} 没有有效的分账记录，无法计算退款比例");
            return [];
        }

        // 遍历有分账记录的供应商（而不是有商品的供应商）
        foreach ($supplierReceivedMap as $supplierId => $supplierShareAmount) {
            $supplierInfo = $suppliers[$supplierId] ?? null;

            // 跳过没有银联商户号的供应商
            if (!$supplierInfo || empty($supplierInfo['unionpay_mid'])) {
                Log::warning("订单 {$orderId} 供应商ID:{$supplierId} 未配置银联商户号，跳过退款分账");
                continue;
            }

            // 检查分账金额
            if ($supplierShareAmount <= 0) {
                Log::info("订单 {$orderId} 供应商{$supplierId} 分账金额为0，跳过");
                continue;
            }

            // 计算该供应商应退金额 = 退款金额 * (该供应商分账金额 / 总分账金额)
            $supplierRefundAmount = bcmul(
                (string)$refundAmount,
                bcdiv((string)$supplierShareAmount, (string)$totalShareAmount, 6),
                2
            );

            if ($supplierRefundAmount <= 0) {
                Log::info("订单 {$orderId} 供应商{$supplierId} 计算退款金额为0，跳过");
                continue;
            }

            // 查询该供应商已退金额
            // 对于多供应商订单，需要查询主订单和所有子订单的退款流水
            /** @var \app\services\supplier\finance\SupplierFlowingWaterServices $waterServices */
            $waterServices = app()->make(\app\services\supplier\finance\SupplierFlowingWaterServices::class);

            // 8.1 查询主订单的退款流水
            $supplierRefundWater = $waterServices->getRefundNumbersByOrder(
                (int)$supplierId,
                (string)$order['order_id']
            );
            $supplierRefundedAmount = array_sum($supplierRefundWater);

            // 8.2 查询子订单的退款流水（多供应商订单的流水可能在子订单上）
            if (!empty($subOrdersList)) {
                foreach ($subOrdersList as $subOrder) {
                    // 只查询当前供应商的子订单
                    if (($subOrder['supplier_id'] ?? 0) == $supplierId) {
                        $subOrderRefundWater = $waterServices->getRefundNumbersByOrder(
                            (int)$supplierId,
                            (string)$subOrder['order_id']
                        );
                        $supplierRefundedAmount = bcadd($supplierRefundedAmount, array_sum($subOrderRefundWater), 2);
                    }
                }
            }

            // 计算该供应商剩余可退金额
            $supplierAvailableRefund = bcsub($supplierShareAmount, (string)$supplierRefundedAmount, 2);

            Log::info("订单 {$orderId} 供应商{$supplierId}: 分账金额={$supplierShareAmount}, 已退={$supplierRefundedAmount}, 可退={$supplierAvailableRefund}, 本次应退={$supplierRefundAmount}");

            // 限制退款金额不超过可退金额
            if (bccomp((string)$supplierRefundAmount, $supplierAvailableRefund, 2) > 0) {
                Log::warning("订单 {$orderId} 供应商{$supplierId} 退款金额({$supplierRefundAmount})超过可退金额({$supplierAvailableRefund})，已调整");
                $supplierRefundAmount = $supplierAvailableRefund;
            }

            if ($supplierRefundAmount <= 0) {
                continue;
            }

            // 生成供应商子订单号
            $supplierSubOrderId = 'SUB_' . $subOrderBase . '_' . $supplierId;
            if (str_starts_with($subOrderBase, '3HD3')) {
                $orderIdWithoutPrefix = substr($subOrderBase, 4);
                $supplierSubOrderId = '3HD3SUB_' . $orderIdWithoutPrefix . '_' . $supplierId;
            }

            // 转换为分
            $supplierRefundAmountFen = bcmul($supplierRefundAmount, '100', 0);

            $subOrders[] = [
                'mid' => $supplierInfo['unionpay_mid'],
                'merOrderId' => $supplierSubOrderId,
                'totalAmount' => $supplierRefundAmountFen,
            ];

            $totalSupplierRefund = bcadd($totalSupplierRefund, $supplierRefundAmount, 2);
            Log::info("订单 {$orderId} 添加供应商{$supplierId}退款分账: 金额={$supplierRefundAmount}元, 子订单号={$supplierSubOrderId}");
        }

        // 9. 添加平台子订单（如果有剩余金额）
        $platformRefundAmount = bcsub((string)$refundAmount, $totalSupplierRefund, 2);

        if (bccomp($platformRefundAmount, '0', 2) > 0) {
            // 读取平台分账配置
            $configFile = config_path() . 'UmsPayConfig.json';
            if (file_exists($configFile)) {
                $config = json_decode(file_get_contents($configFile), true);
                $platformDivision = $config['platform_division'] ?? null;

                if ($platformDivision && !empty($platformDivision['mid'])) {
                    // 生成平台子订单号
                    $platformSubOrderId = 'PLAT_' . $subOrderBase;
                    if (str_starts_with($subOrderBase, '3HD3')) {
                        $orderIdWithoutPrefix = substr($subOrderBase, 4);
                        $platformSubOrderId = '3HD3PLAT_' . $orderIdWithoutPrefix;
                    }

                    // 检查平台子订单是否存在
                    $platformSubOrderExists = $this->checkPlatformSubOrderExists($order, $platformSubOrderId);

                    if ($platformSubOrderExists) {
                        $platformRefundAmountFen = bcmul($platformRefundAmount, '100', 0);

                        $subOrders[] = [
                            'mid' => $platformDivision['mid'],
                            'merOrderId' => $platformSubOrderId,
                            'totalAmount' => $platformRefundAmountFen,
                        ];

                        Log::info("订单 {$orderId} 添加平台退款分账: 金额={$platformRefundAmount}元, 子订单号={$platformSubOrderId}");
                    } else {
                        Log::info("订单 {$orderId} 平台子订单不存在: {$platformSubOrderId}，跳过平台退款分账");
                    }
                }
            }
        }

        if (empty($subOrders)) {
            Log::warning("订单 {$orderId} 没有构建任何退款分账子订单");
            return [];
        }

        // 10. 构造分账退款参数
        $divisionData = [
            'platformAmount' => 0,
            'subOrders' => $subOrders
        ];

        Log::info("订单 {$orderId} 多供应商退款分账数据构建成功: 子订单数=" . count($subOrders));

        return $divisionData;

    } catch (\Exception $e) {
        Log::error("构建多供应商退款分账数据失败: " . $e->getMessage());
        return [];
    }
}

