/**
 * 多次退款测试
 * 支持连续进行多次退款操作，每次退款使用不同的退款订单号
 */
function runMultiRefund(array $account, string $orderId, array $opts): void
{
    echo "========================================\n";
    echo "多次退款测试\n";
    echo "========================================\n";
    echo "原订单号: {$orderId}\n\n";

    $refundCount = 0;
    $totalRefunded = '0.00';

    while (true) {
        $refundCount++;
        echo "--- 第 {$refundCount} 次退款 ---\n";

        // 输入退款金额
        echo "请输入退款金额(元,输入q退出): ";
        $inputAmount = trim(fgets(STDIN));

        if (strtolower($inputAmount) === 'q') {
            echo "\n已退出退款流程\n";
            break;
        }

        if (empty($inputAmount)) {
            echo "❌ 退款金额不能为空\n\n";
            $refundCount--;
            continue;
        }

        if (!is_numeric($inputAmount) || $inputAmount <= 0) {
            echo "❌ 无效的退款金额: {$inputAmount}\n\n";
            $refundCount--;
            continue;
        }

        // 生成唯一的退款订单号（带序号）
        $refundOrderId = 'RF' . date('YmdHis') . rand(1000, 9999) . '_' . $refundCount;

        $payload = [
            'requestTimestamp' => date('Y-m-d H:i:s'),
            'mid' => $account['mid'],
            'tid' => $account['tid'],
            'merOrderId' => formatOrderId($orderId, $account),
            'refundOrderId' => formatOrderId($refundOrderId, $account),
            'refundAmount' => amountToFen($inputAmount),
            'totalAmount' => amountToFen($inputAmount),
            'orderDesc' => '测试退款第' . $refundCount . '次',
        ];

        echo "退款订单号: {$refundOrderId}\n";
        echo "退款金额: {$inputAmount}元\n\n";

        $response = executeUmsCall("发起第{$refundCount}次退款", $account, '/v1/netpay/refund', $payload);

        if (isset($response['errCode']) && $response['errCode'] === 'SUCCESS') {
            $totalRefunded = bcadd($totalRefunded, $inputAmount, 2);
            echo "✅ 第 {$refundCount} 次退款成功\n";
            echo "累计退款金额: {$totalRefunded}元\n\n";
        } else {
            echo "❌ 第 {$refundCount} 次退款失败\n\n";
        }

        // 询问是否继续
        echo "是否继续退款? (y/n,默认y): ";
        $continue = trim(fgets(STDIN));
        if (strtolower($continue) === 'n') {
            echo "\n退款流程结束\n";
            break;
        }
        echo "\n";
    }

    echo "========================================\n";
    echo "多次退款测试完成\n";
    echo "总退款次数: {$refundCount}\n";
    echo "累计退款金额: {$totalRefunded}元\n";
    echo "========================================\n";
}

